def transform(grid):
    """Transform grid by finding 3x3 uniform blocks and drawing full horizontal/vertical lines."""
    import numpy as np
    import json
    grid = np.array(grid)
    rows, cols = grid.shape
    result = grid.copy()

    # Find all 3x3 uniform blocks (each row in the 3x3 must be uniform)
    blocks = []
    for r in range(rows-2):
        for c in range(cols-2):
            is_uniform = True
            for rr in range(3):
                row_region = grid[r+rr][c:c+3]
                if len(set(row_region)) != 1 or row_region[0] == 0:
                    is_uniform = False
                    break
            if is_uniform:
                block_color = grid[r+1][c]
                center_r, center_c = r+1, c+1
                blocks.append((center_r, center_c, block_color))

    # Draw full horizontal and vertical lines at each center
    for cr, cc, color in blocks:
        for c in range(cols):
            result[cr][c] = color
        for r in range(rows):
            result[r][cc] = color

    # Find intersection points where any horizontal crosses any vertical
    # Gap at (block_i_row, block_j_col) for all pairs
    intersection_points = set()
    for i, (bi_r, bi_c, bi_color) in enumerate(blocks):
        for j, (bj_r, bj_c, bj_color) in enumerate(blocks):
            if i != j:
                # Horizontal from block i crosses vertical from block j
                intersection_points.add((bi_r, bj_c))

    # Set intersection points to 0
    for r, c in intersection_points:
        result[r, c] = 0

    return result.tolist()

